    public function resolve(string $code, User $actor, ?int $branchId = null): array
    {
        [$title, $reason, $next, $topic] = $this->definitions()[$code] ?? $this->definitions()['request.invalid'];
        $link = $topic ? $this->knowledge->link($topic, $actor, $branchId) : null;
        if ($topic !== null && $link === null) {
            $next = 'شاشة معالجة هذا السبب غير متاحة لصلاحياتك. اطلب من المالك أو المسؤول المخوّل مراجعته، ثم أعد المحاولة بعد تأكيده. المساعد لا يمنح صلاحيات ولا يتجاوز المنع.';
        }

        return ['code' => isset($this->definitions()[$code]) ? $code : 'request.invalid', 'title' => $title,
            'message' => $reason, 'reason' => $reason, 'next_step' => $next,
            'action_label' => $link ? 'فتح '.$link['label'] : null, 'action_url' => $link['url'] ?? null,
            'severity' => 'warning', 'context' => []];
    }

    public function legacyCode(string $message): ?string
    {
        foreach (['رصيد قديم بلا مستند افتتاحي موثّق' => 'stock.source_unproven', 'يلزم تهيئة صلاحيات المبيعات وحسابات الاستلام' => 'sales.setup_required', 'أُغلق إعداد أول المدة' => 'opening.closed', 'المورد مؤرشف' => 'purchases.supplier_archived',
            'لم يثبت القيد الأصلي للفاتورة' => 'returns.original_unproven', 'رصيد بداية الحساب غير معتمد' => 'accounts.opening_required',
            'تغيرت الفاتورة' => 'document.changed', 'تغيرت الجاهزية' => 'document.changed', 'تغيرت بيانات صنف' => 'document.changed',
            'تغيرت السلة' => 'document.changed', 'الفترة المالية مغلقة' => 'finance.closed_period'] as $fragment => $code) {
            if (str_contains($message, $fragment)) {
                return $code;
            }
        }

        return null;
    }
}
